ALTER TABLE USER_LOGIN_HISTORY
    ADD COLUMN IF NOT EXISTS BRAND_ID CHAR (36),
    ADD COLUMN IF NOT EXISTS BRAND_NAME VARCHAR (255);

ALTER TABLE USER_POST
    ADD COLUMN IF NOT EXISTS MARK_BRAND_ID CHAR (36),
    ADD CONSTRAINT FK_USER_POST_BRAND FOREIGN KEY (MARK_BRAND_ID) REFERENCES BRAND(ID);

ALTER TABLE IMPORT_USERS_DATA
    ADD COLUMN IF NOT EXISTS MARK_BRAND_ID CHAR (36),
    ADD CONSTRAINT FK_IMPORT_USERS_DATA_BRAND FOREIGN KEY (MARK_BRAND_ID) REFERENCES BRAND(ID);
